#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_SESSIONS 256
#define SESSION_ID_LEN 32
#define MAX_RETRIES 5
#define RATE_LIMIT_WINDOW 60
#define RATE_LIMIT_MAX 100

typedef struct {
    char session_id[SESSION_ID_LEN + 1];
    char username[64];
    time_t created_at;
    time_t last_activity;
    int authenticated;
    int privilege_level;
} session_t;

typedef struct {
    int request_count;
    time_t window_start;
    char client_id[64];
} rate_limit_entry_t;

typedef struct {
    char task_id[64];
    char session_id[SESSION_ID_LEN + 1];
    int retry_count;
    int (*handler)(void *ctx);
    void *context;
    time_t scheduled_at;
} job_t;

static session_t session_store[MAX_SESSIONS];
static rate_limit_entry_t rate_limits[MAX_SESSIONS];
static pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t rate_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Returns 0 on success, -1 on failure to obtain secure randomness. */
static int generate_session_id(char *buf, size_t len) {
    static const char charset[] = "abcdef0123456789";
    FILE *urandom = fopen("/dev/urandom", "r");
    if (!urandom) {
        /* No secure source available: fail closed rather than fall back to
         * predictable rand(). */
        return -1;
    }
    unsigned char randbuf[SESSION_ID_LEN];
    if (len > sizeof(randbuf)) {
        fclose(urandom);
        return -1;
    }
    size_t got = fread(randbuf, 1, len, urandom);
    fclose(urandom);
    if (got != len) {
        /* Partial read: do not derive an ID from uninitialized bytes. */
        return -1;
    }
    for (size_t i = 0; i < len; i++) {
        buf[i] = charset[randbuf[i] % (sizeof(charset) - 1)];
    }
    buf[len] = '\0';
    return 0;
}

static int check_rate_limit(const char *client_id) {
    pthread_mutex_lock(&rate_mutex);
    time_t now = time(NULL);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (strcmp(rate_limits[i].client_id, client_id) == 0) {
            if (now - rate_limits[i].window_start > RATE_LIMIT_WINDOW) {
                rate_limits[i].window_start = now;
                rate_limits[i].request_count = 1;
                pthread_mutex_unlock(&rate_mutex);
                return 0;
            }
            if (rate_limits[i].request_count >= RATE_LIMIT_MAX) {
                pthread_mutex_unlock(&rate_mutex);
                return -1;
            }
            rate_limits[i].request_count++;
            pthread_mutex_unlock(&rate_mutex);
            return 0;
        }
    }
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (rate_limits[i].client_id[0] == '\0') {
            strncpy(rate_limits[i].client_id, client_id, 63);
            rate_limits[i].client_id[63] = '\0';
            rate_limits[i].window_start = now;
            rate_limits[i].request_count = 1;
            pthread_mutex_unlock(&rate_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&rate_mutex);
    return -1;
}

/* Caller must hold session_mutex. */
static session_t *find_session_locked(const char *session_id) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (strcmp(session_store[i].session_id, session_id) == 0) {
            return &session_store[i];
        }
    }
    return NULL;
}

static session_t *find_session(const char *session_id) {
    pthread_mutex_lock(&session_mutex);
    session_t *sess = find_session_locked(session_id);
    pthread_mutex_unlock(&session_mutex);
    return sess;
}

static session_t *create_session(const char *username) {
    pthread_mutex_lock(&session_mutex);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_store[i].session_id[0] == '\0') {
            if (generate_session_id(session_store[i].session_id, SESSION_ID_LEN) != 0) {
                pthread_mutex_unlock(&session_mutex);
                return NULL;
            }
            strncpy(session_store[i].username, username, 63);
            session_store[i].username[63] = '\0';
            session_store[i].created_at = time(NULL);
            session_store[i].last_activity = time(NULL);
            session_store[i].authenticated = 1;
            session_store[i].privilege_level = 1;
            pthread_mutex_unlock(&session_mutex);
            return &session_store[i];
        }
    }
    pthread_mutex_unlock(&session_mutex);
    return NULL;
}

/* Session binding for job worker - always generates a new server-side session */
static int bind_job_session(job_t *job, const char *provided_session_id) {
    pthread_mutex_lock(&session_mutex);

    session_t *existing = find_session_locked(provided_session_id);

    /* If session exists and is already authenticated, reuse it */
    if (existing != NULL && existing->authenticated) {
        strncpy(job->session_id, existing->session_id, SESSION_ID_LEN);
        job->session_id[SESSION_ID_LEN] = '\0';
        pthread_mutex_unlock(&session_mutex);
        return 0;
    }

    /* No valid authenticated session - generate a fresh server-controlled
     * session ID. Never accept client-provided IDs for new sessions. */
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_store[i].session_id[0] == '\0') {
            if (generate_session_id(session_store[i].session_id, SESSION_ID_LEN) != 0) {
                pthread_mutex_unlock(&session_mutex);
                return -1;
            }
            session_store[i].created_at = time(NULL);
            session_store[i].last_activity = time(NULL);
            session_store[i].authenticated = 0;
            session_store[i].privilege_level = 0;
            strncpy(job->session_id, session_store[i].session_id, SESSION_ID_LEN);
            job->session_id[SESSION_ID_LEN] = '\0';
            pthread_mutex_unlock(&session_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&session_mutex);
    return -1;
}

/* Authenticate and elevate a session after job validation */
static int elevate_session_post_auth(const char *session_id, const char *username) {
    pthread_mutex_lock(&session_mutex);
    session_t *sess = find_session_locked(session_id);
    if (sess != NULL) {
        /* Session found - mark as authenticated and elevate */
        strncpy(sess->username, username, 63);
        sess->username[63] = '\0';
        sess->authenticated = 1;
        sess->privilege_level = 2;
        sess->last_activity = time(NULL);
        pthread_mutex_unlock(&session_mutex);
        return 0;
    }
    pthread_mutex_unlock(&session_mutex);
    return -1;
}

static int execute_job_with_retry(job_t *job, const char *client_id) {
    int result = -1;

    for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
        if (check_rate_limit(client_id) != 0) {
            fprintf(stderr, "[worker] Rate limit exceeded for %s\n", client_id);
            return -2;
        }

        job->retry_count = attempt;

        if (job->handler != NULL) {
            result = job->handler(job->context);
            if (result == 0) {
                /* Success - elevate session privileges for completed job */
                elevate_session_post_auth(job->session_id, "worker_service");
                break;
            }
        }

        /* Exponential backoff */
        unsigned int delay = (1 << attempt) * 100000;
        usleep(delay > 3200000 ? 3200000 : delay);
    }

    return result;
}

static int sample_handler(void *ctx) {
    (void)ctx;
    return 0;
}

int process_incoming_job(const char *client_id, const char *session_id_hint,
                         const char *task_id) {
    job_t job;
    memset(&job, 0, sizeof(job));

    strncpy(job.task_id, task_id, 63);
    job.task_id[63] = '\0';
    job.handler = sample_handler;
    job.context = NULL;
    job.scheduled_at = time(NULL);

    /* Bind session - server always controls session ID generation */
    if (bind_job_session(&job, session_id_hint) != 0) {
        return -1;
    }

    return execute_job_with_retry(&job, client_id);
}

int main(void) {
    srand((unsigned int)time(NULL));
    memset(session_store, 0, sizeof(session_store));
    memset(rate_limits, 0, sizeof(rate_limits));

    /* Simulate: legitimate user creates a session */
    session_t *user_sess = create_session("admin_user");
    if (user_sess) {
        printf("[main] Admin session created: %s (priv=%d)\n",
               user_sess->session_id, user_sess->privilege_level);
    }

    /* Simulate: attacker submits job with a chosen session ID */
    const char *attacker_chosen_id = "deadbeefdeadbeefdeadbeefdeadbeef";
    printf("[main] Processing job with hint: %s\n", attacker_chosen_id);
    process_incoming_job("attacker_client", attacker_chosen_id, "task_001");

    /* Check: attacker's pre-set session should NOT exist */
    session_t *fixed_sess = find_session(attacker_chosen_id);
    if (fixed_sess == NULL) {
        printf("[SAFE] Attacker's chosen session ID was not registered\n");
    } else {
        printf("[INFO] Session state: auth=%d priv=%d\n",
               fixed_sess->authenticated, fixed_sess->privilege_level);
    }

    return 0;
}
